describe('Form Submission Confirmation Email', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual form page URL
    });

    it('should send a confirmation email after successful form submission', () => {
        cy.get('input[name="name"]').type('John Doe');
        cy.get('input[name="email"]').type('john.doe@example.com');
        cy.get('textarea[name="message"]').type('This is a test message.');
        cy.get('button[type="submit"]').click();

        cy.get('.success-message').should('be.visible').and('contain', 'Thank you for your submission!');
        cy.wait(2000); // Wait for the email to be sent

        cy.request('GET', '/api/emails') // Replace with the actual API endpoint to check emails
            .its('body')
            .should('deep.include', {
                to: 'john.doe@example.com',
                subject: 'Confirmation of your submission',
                body: 'Thank you for your submission!'
            });
    });

    it('should not send a confirmation email if the form is submitted with an invalid email', () => {
        cy.get('input[name="name"]').type('John Doe');
        cy.get('input[name="email"]').type('invalid-email');
        cy.get('textarea[name="message"]').type('This is a test message.');
        cy.get('button[type="submit"]').click();

        cy.get('.error-message').should('be.visible').and('contain', 'Please enter a valid email address.');
        cy.wait(2000); // Wait for the email to be processed

        cy.request('GET', '/api/emails') // Replace with the actual API endpoint to check emails
            .its('body')
            .should('not.deep.include', {
                to: 'invalid-email',
                subject: 'Confirmation of your submission',
                body: 'Thank you for your submission!'
            });
    });
});
